   153→## Component Implementation Patterns
   154→
   155→### Lit Component Base Pattern
   156→
   157→**Standard Component Structure**:
   158→
   159→```typescript
   160→@customElement("component-name")
   161→export class ComponentName extends LitElement {
   162→    @property({ type: Array }) data: DataType[] = [];
   163→    
   164→    createRenderRoot() {
   165→        return this; // Access global CSS
   166→    }
   167→
   168→    render() {
   169→        return html`
   170→            <div class="component-container">
   171→                ${this.data.map(item => this.renderItem(item))}
   172→            </div>
   173→        `;
   174→    }
   175→
   176→    private renderItem(item: DataType): TemplateResult {
   177→        return html`<div class="item">${item.content}</div>`;
   178→    }
   179→}
   180→```
