   222→private processConversationData(conversations: SimpleConversation[]): ProcessedConversation[] {
   223→    return conversations.map(conversation => ({
   224→        ...conversation,
   225→        id: conversation.id || crypto.randomUUID(),
   226→        timestamp: conversation.messages[0]?.timestamp || Date.now(),
   227→        messageCount: conversation.messages.length,
   228→        toolCalls: this.extractToolCalls(conversation),
   229→        systemPrompt: this.extractSystemPrompt(conversation)
   230→    }));
   231→}
   232→
   233→private extractToolCalls(conversation: SimpleConversation): ToolCallInfo[] {
   234→    return conversation.messages
   235→        .flatMap(message => message.content || [])
   236→        .filter((content): content is ToolUseBlockParam => content.type === 'tool_use')
   237→        .map(toolUse => ({
   238→            id: toolUse.id,
   239→            name: toolUse.name,
   240→            input: toolUse.input
   241→        }));
