   275→### Input Validation Implementation
   276→
   277→**Runtime Type Validation Pattern**:
   278→
   279→```typescript
   280→private validateConversationData(data: unknown): data is ClaudeData {
   281→    if (!data || typeof data !== 'object') {
   282→        return false;
   283→    }
   284→    
   285→    const claudeData = data as ClaudeData;
   286→    
   287→    return Array.isArray(claudeData.rawPairs) &&
   288→           claudeData.rawPairs.every(pair => 
   289→               pair.request && pair.response && 
   290→               typeof pair.request.url === 'string'
   291→           );
   292→}
   293→
   294→private loadData(): void {
   295→    const windowData = (window as any).claudeData;
   296→    
   297→    if (this.validateConversationData(windowData)) {
   298→        this.data = windowData;
   299→    } else {
   300→        console.error('Invalid conversation data format');
   301→        this.data = { rawPairs: [] };
   302→    }
   303→}
