   328→private handleConversationClick(e: Event): void {
   329→    const details = (e.currentTarget as HTMLElement)
   330→        .querySelector('.conversation-details') as HTMLElement;
   331→    
   332→    if (details.style.display === 'none') {
   333→        // Lazy load detailed content only when expanded
