   359→## Testing Patterns for Components
   360→
   361→### Component Testing Utilities
   362→
   363→```typescript
   364→// Test helper for component setup
   365→export function setupComponent<T extends LitElement>(
   366→    ComponentClass: new () => T,
   367→    props: Partial<T> = {}
   368→): T {
   369→    const component = new ComponentClass();
   370→    Object.assign(component, props);
   371→    
   372→    document.body.appendChild(component);
   373→    return component;
   374→}
   375→
   376→// Mock data generators
   377→export function createMockConversation(): SimpleConversation {
   378→    return {
   379→        id: crypto.randomUUID(),
   380→        messages: [createMockMessage()],
   381→        model: 'claude-3-sonnet-20240229',
   382→        systemPrompt: 'Test system prompt'
   383→    };
   384→}
   385→
   386→// Async testing pattern
   387→export async function testComponentRender<T extends LitElement>(
   388→    component: T,
   389→    expectedContent: string
   390→): Promise<void> {
   391→    await component.updateComplete;
   392→    const content = component.shadowRoot?.textContent || component.textContent;
   393→    assert(content?.includes(expectedContent), 'Component should render expected content');
   394→}
   395→```
   396→
   397→## Accessibility Implementation
   398→
   399→### Keyboard Navigation
   400→
   401→```typescript
   402→// Keyboard event handling
   403→private handleKeyDown = (e: KeyboardEvent): void => {
   404→    switch (e.key) {
   405→        case 'Enter':
   406→        case ' ':
   407→            e.preventDefault();
   408→            this.toggleContent(e);
   409→            break;
   410→        case 'ArrowDown':
   411→            e.preventDefault();
   412→            this.focusNext();
   413→            break;
   414→        case 'ArrowUp':
   415→            e.preventDefault();
   416→            this.focusPrevious();
   417→            break;
   418→    }
   419→}
   420→
   421→// ARIA attributes for screen readers
   422→private renderAccessibleButton(content: string, expanded: boolean): TemplateResult {
   423→    return html`
   424→        <button 
   425→            class="accessible-toggle"
   426→            aria-expanded=${expanded}
   427→            aria-controls="content-section"
   428→            @keydown=${this.handleKeyDown}
   429→        >
   430→            ${content}
   431→        </button>
   432→    `;
   433→}
   434→```
