    56→function escapeHtml(text: string): string {
    57→    return text
    58→        .replace(/&/g, "&amp;")      // Must be first to avoid double-escaping
    59→        .replace(/</g, "&lt;")       // Prevent tag injection
    60→        .replace(/>/g, "&gt;")       // Prevent tag injection
    61→        .replace(/"/g, "&quot;")     // Prevent attribute injection
    62→        .replace(/'/g, "&#39;")      // Prevent attribute injection
    63→        .replace(/\//g, "&#x2F;");   // Additional safety for forward slashes
    64→}
