   200→// Debounced async processing utility
   201→export function createDebouncedProcessor<T, R>(
   202→    processor: (input: T) => Promise<R>,
   203→    delay: number = 300
   204→): (input: T) => Promise<R> {
   205→    let timeoutId: number | null = null;
   206→    let latestPromise: Promise<R> | null = null;
   207→    
   208→    return (input: T): Promise<R> => {
   209→        // Cancel previous timeout
   210→        if (timeoutId !== null) {
   211→            clearTimeout(timeoutId);
   212→        }
   213→        
   214→        // Create new debounced promise
   215→        latestPromise = new Promise((resolve, reject) => {
   216→            timeoutId = window.setTimeout(async () => {
   217→                try {
   218→                    const result = await processor(input);
   219→                    resolve(result);
   220→                } catch (error) {
   221→                    reject(error);
   222→                }
   223→                timeoutId = null;
   224→            }, delay);
   225→        });
   226→        
   227→        return latestPromise;
   228→    };
   229→}
