   218→                    const result = await processor(input);
   219→                    resolve(result);
   220→                } catch (error) {
   221→                    reject(error);
   222→                }
   223→                timeoutId = null;
   224→            }, delay);
   225→        });
   226→        
   227→        return latestPromise;
   228→    };
   229→}
   230→
   231→// Usage for markdown processing with debouncing
   232→const debouncedMarkdownProcessor = createDebouncedProcessor(
   233→    async (content: string) => markdownToHtml(content),
   234→    200
   235→);
   236→```
   237→
   238→## Testing Utilities Implementation
   239→
   240→### Markdown Testing Utilities
   241→
   242→```typescript
   243→// Test helpers for markdown processing
   244→export function createMarkdownTestSuite() {
   245→    return {
   246→        // Test basic markdown features
   247→        testBasicMarkdown(): void {
   248→            const input = '# Header\n**bold** text';
   249→            const output = markdownToHtml(input);
   250→            
   251→            assert(output.includes('<h1>'), 'Should convert headers');
   252→            assert(output.includes('<strong>'), 'Should convert bold text');
   253→        },
   254→        
   255→        // Test XSS prevention
   256→        testXSSPrevention(): void {
   257→            const maliciousInput = '<script>alert("xss")</script>';
   258→            const output = markdownToHtml(maliciousInput);
   259→            
   260→            assert(!output.includes('<script>'), 'Should escape script tags');
   261→            assert(output.includes('&lt;script&gt;'), 'Should show escaped content');
   262→        },
   263→        
   264→        // Test error handling
   265→        testErrorHandling(): void {
   266→            // Test with null/undefined inputs
   267→            assert(markdownToHtml('') === '', 'Should handle empty input');
   268→            
   269→            // Test with malformed input that might cause marked to throw
   270→            const problematicInput = '\x00\x01\x02'; // Control characters
   271→            const output = markdownToHtml(problematicInput);
   272→            
   273→            // Should not throw and should return safe content
   274→            assert(typeof output === 'string', 'Should return string even on error');
   275→        }
   276→    };
   277→}
   278→```
   279→
   280→### Utility Testing Pattern
   281→
   282→```typescript
   283→// Generic utility testing helper
   284→export function testUtilityFunction<T, R>(
   285→    utilityFn: (input: T) => R,
   286→    testCases: Array<{ input: T; expected: R; description: string }>
   287→): void {
   288→    testCases.forEach(({ input, expected, description }) => {
   289→        try {
   290→            const result = utilityFn(input);
   291→            assert(
   292→                JSON.stringify(result) === JSON.stringify(expected),
   293→                `${description}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(result)}`
   294→            );
   295→            console.log(`✓ ${description}`);
   296→        } catch (error) {
   297→            console.error(`✗ ${description}:`, error);
   298→            throw error;
   299→        }
   300→    });
   301→}
   302→
   303→// Usage example
   304→testUtilityFunction(markdownToHtml, [
   305→    {
   306→        input: '**bold**',
   307→        expected: '<p><strong>bold</strong></p>\n',
   308→        description: 'Should convert bold markdown'
   309→    },
   310→    {
   311→        input: '<script>alert("test")</script>',
   312→        expected: '<p>&lt;script&gt;alert(&quot;test&quot;)&lt;/script&gt;</p>\n',
   313→        description: 'Should escape HTML tags'
   314→    }
   315→]);
   316→```
   317→
   318→## Performance Monitoring Utilities
   319→
   320→### Performance Measurement Pattern
   321→
   322→```typescript
   323→// Performance monitoring utility for expensive operations
   324→export function measurePerformance<T>(
   325→    operation: () => T,
   326→    operationName: string,
   327→    logThreshold: number = 10 // ms
   328→): T {
   329→    const start = performance.now();
   330→    const result = operation();
   331→    const duration = performance.now() - start;
   332→    
   333→    if (duration > logThreshold) {
   334→        console.log(`⚡ ${operationName} took ${duration.toFixed(2)}ms`);
   335→    }
   336→    
   337→    return result;
   338→}
   339→
   340→// Usage in markdown processing
   341→export function performantMarkdownToHtml(content: string): string {
   342→    return measurePerformance(
   343→        () => markdownToHtml(content),
   344→        `Markdown processing (${content.length} chars)`,
   345→        5 // Log if takes more than 5ms
   346→    );
   347→}
   348→```
   349→
   350→## Future Utility Expansion
   351→
   352→### Planned Utility Categories
   353→
   354→When expanding the utils directory, follow these patterns:
   355→
   356→1. **Date/Time Utilities**: Consistent timestamp formatting
   357→2. **String Processing**: Text manipulation and validation
   358→3. **API Helpers**: Request/response formatting utilities
   359→4. **Validation Utilities**: Type guards and data validation
   360→5. **Performance Utilities**: Caching and optimization helpers
   361→
   362→### Utility Development Standards
   363→
   364→**Type Safety Requirements**:
   365→- Use proper TypeScript interfaces, avoid `any` types
   366→- Provide type guards for runtime validation
   367→- Include comprehensive error handling with typed exceptions
   368→
   369→**Security Requirements**:
   370→- Treat all external input as potentially malicious
   371→- Implement proper sanitization for content processing
   372→- Use secure defaults in all utility configurations
   373→
   374→**Performance Requirements**:
   375→- Include performance monitoring for expensive operations
   376→- Implement caching where appropriate
   377→- Use efficient algorithms for data processing
   378→
   379→**Testing Requirements**:
   380→- Provide test utilities alongside production utilities
   381→- Include edge case testing for all public functions
   382→- Test error handling paths thoroughly
   383→
   384→This implementation guide provides practical patterns for developing secure, performant, and maintainable utility functions that support the Claude Trace frontend application.

